class DefaultEvaluationStrategyValueExprErrorTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void successfulConstantMathRemainsConstant() throws Exception {
		DefaultEvaluationStrategy strategy = strategy();
		MathExpr expression = new MathExpr(new ValueConstant(VF.createLiteral(1)),
				new ValueConstant(VF.createLiteral(2)), MathExpr.MathOp.PLUS);

		QueryValueEvaluationStep step = strategy.precompile(expression, context());

		assertThat(step.isConstant()).isTrue();
		assertThat(step.evaluate(EmptyBindingSet.getInstance()).stringValue()).isEqualTo("3");
	}

	@Test
	void ordinaryQueryEvaluationExceptionsStillPropagate() {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null) {
			@Override
			protected QueryValueEvaluationStep prepare(Var var, QueryEvaluationContext context)
					throws QueryEvaluationException {
				throw new QueryEvaluationException("ordinary preparation failure");
			}
		};

		assertThatThrownBy(() -> strategy.precompile(Var.of("value"), context()))
				.isExactlyInstanceOf(QueryEvaluationException.class)
				.hasMessage("ordinary preparation failure");
	}

	@Test
	void ifDefersConstantMathErrorUntilSelectedBranch() throws Exception {
		DefaultEvaluationStrategy strategy = strategy();
		If expression = new If(new Var("flag"), divideByZero(), constant("fallback"));

		QueryValueEvaluationStep step = assertDoesNotThrow(
				() -> strategy.precompile(expression, context()));

		assertThat(step.evaluate(binding("flag", false))).isEqualTo(value("fallback"));
		assertThatThrownBy(() -> step.evaluate(binding("flag", true)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void ifDefersErrorInAlternativeUntilSelectedBranch() throws Exception {
		DefaultEvaluationStrategy strategy = strategy();
		If expression = new If(new Var("flag"), constant("result"), divideByZero());

		QueryValueEvaluationStep step = assertDoesNotThrow(
				() -> strategy.precompile(expression, context()));

		assertThat(step.evaluate(binding("flag", true))).isEqualTo(value("result"));
		assertThatThrownBy(() -> step.evaluate(binding("flag", false)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void nestedIfOnlyEvaluatesTheSelectedErrorArm() throws Exception {
		DefaultEvaluationStrategy strategy = strategy();
		If nested = new If(new Var("nested"), divideByZero(), constant("inner"));
		If expression = new If(new Var("outer"), nested, constant("outer"));

		QueryValueEvaluationStep step = assertDoesNotThrow(
				() -> strategy.precompile(expression, context()));

		assertThat(step.evaluate(binding("outer", false))).isEqualTo(value("outer"));
		assertThat(step.evaluate(binding("outer", true, "nested", false))).isEqualTo(value("inner"));
		assertThatThrownBy(() -> step.evaluate(binding("outer", true, "nested", true)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void coalesceUsesFallbackAfterConstantExpressionError() throws Exception {
		DefaultEvaluationStrategy strategy = strategy();
		Coalesce expression = new Coalesce(List.of(divideByZero(), constant("fallback")));

		QueryValueEvaluationStep step = assertDoesNotThrow(
				() -> strategy.precompile(expression, context()));

		assertThat(step.evaluate(EmptyBindingSet.getInstance())).isEqualTo(value("fallback"));
	}

	@Test
	void logicalOperatorsPreserveShortCircuitAndSelectedErrors() throws Exception {
		DefaultEvaluationStrategy strategy = strategy();
		Not invalidBoolean = new Not(new ValueConstant(VF.createIRI("urn:test:not-a-boolean")));

		QueryValueEvaluationStep andShortCircuit = assertDoesNotThrow(
				() -> strategy.precompile(new And(new ValueConstant(VF.createLiteral(false)), invalidBoolean),
						context()));
		assertThat(andShortCircuit.evaluate(EmptyBindingSet.getInstance())).isEqualTo(VF.createLiteral(false));

		QueryValueEvaluationStep andSelected = assertDoesNotThrow(
				() -> strategy.precompile(new And(new ValueConstant(VF.createLiteral(true)),
						new Not(new ValueConstant(VF.createIRI("urn:test:not-a-boolean")))), context()));
		assertThatThrownBy(() -> andSelected.evaluate(EmptyBindingSet.getInstance()))
				.isInstanceOf(ValueExprEvaluationException.class);

		QueryValueEvaluationStep orShortCircuit = assertDoesNotThrow(
				() -> strategy.precompile(new Or(new ValueConstant(VF.createLiteral(true)),
						new Not(new ValueConstant(VF.createIRI("urn:test:not-a-boolean")))), context()));
		assertThat(orShortCircuit.evaluate(EmptyBindingSet.getInstance())).isEqualTo(VF.createLiteral(true));

		QueryValueEvaluationStep orSelected = assertDoesNotThrow(
				() -> strategy.precompile(new Or(new ValueConstant(VF.createLiteral(false)),
						new Not(new ValueConstant(VF.createIRI("urn:test:not-a-boolean")))), context()));
		assertThatThrownBy(() -> orSelected.evaluate(EmptyBindingSet.getInstance()))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void bindAndGroupKeepRowsAfterConstantExpressionError() throws Exception {
		DefaultEvaluationStrategy strategy = strategy();
		ParsedQuery bindQuery = QueryParserUtil.parseQuery(QueryLanguage.SPARQL,
				"SELECT ?row WHERE { VALUES ?row { 1 2 3 } BIND(1 / 0 AS ?bad) FILTER(!BOUND(?bad)) }",
				null);
		List<BindingSet> bindResults = QueryResults.asList(
				strategy.precompile(bindQuery.getTupleExpr()).evaluate(EmptyBindingSet.getInstance()));
		assertThat(bindResults).hasSize(3);

		ParsedQuery groupQuery = QueryParserUtil.parseQuery(QueryLanguage.SPARQL,
				"SELECT (COUNT(*) AS ?count) WHERE { VALUES ?row { 1 2 3 } BIND(1 / 0 AS ?bad) "
						+ "FILTER(!BOUND(?bad)) }",
				null);
		List<BindingSet> groupResults = QueryResults.asList(
				strategy.precompile(groupQuery.getTupleExpr()).evaluate(EmptyBindingSet.getInstance()));
		assertThat(groupResults).hasSize(1);
		assertThat(groupResults.get(0).getValue("count").stringValue()).isEqualTo("3");
	}

	private static DefaultEvaluationStrategy strategy() {
		return new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
	}

	private static QueryEvaluationContext context() {
		return new QueryEvaluationContext.Minimal((Dataset) null);
	}

	private static MathExpr divideByZero() {
		return new MathExpr(new ValueConstant(VF.createLiteral(1)), new ValueConstant(VF.createLiteral(0)),
				MathExpr.MathOp.DIVIDE);
	}

	private static Value value(String value) {
		return VF.createLiteral(value);
	}

	private static ValueConstant constant(String value) {
		return new ValueConstant(value(value));
	}

	private static QueryBindingSet binding(Object... values) {
		QueryBindingSet bindings = new QueryBindingSet();
		for (int i = 0; i < values.length; i += 2) {
			bindings.addBinding((String) values[i], VF.createLiteral((boolean) values[i + 1]));
		}
		return bindings;
	}
}
